<div class="full"><label class="label">Phone Number <span style="color:#dc2626">*</span></label><div style="display:grid;grid-template-columns:96px 1fr;gap:8px"><select id="phone-country" class="field" style="padding-left:10px;padding-right:4px" name="phone_country_code" required>@foreach($countries as $country)<option value="{{$country['code']}}" data-dial="{{$country['dial_code']}}" @selected(old('phone_country_code',$profile->phone_country_code?:'IN')===$country['code'])>{{$country['dial_code']}}</option>@endforeach</select><input id="phone" class="field" style="font-size:14px" name="phone" type="tel" inputmode="tel" placeholder="9876543210" value="{{old('phone',$profile->phone)}}" required></div>@error('phone')<div style="color:#b42318">{{$message}}</div>@enderror</div>
<div><label class="label">Country</label><select id="country" class="field" name="country_code"><option value="">Select country</option>@foreach($countries as $country)<option value="{{$country['code']}}" data-name="{{$country['name']}}" @selected(old('country_code',$profile->country_code)===$country['code'])>{{$country['name']}}</option>@endforeach</select></div>
<div><label class="label">State / Region</label><select id="state" class="field" name="state" data-current="{{old('state',$profile->state)}}"><option value="">Select country first</option></select></div>
<div><label class="label">City</label><select id="city" class="field" name="city" data-current="{{old('city',$profile->city)}}"><option value="">Select state first</option></select></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const country=document.getElementById('country'),state=document.getElementById('state'),city=document.getElementById('city');const fill=(el,items,label,current='')=>{el.innerHTML='';el.add(new Option(label,''));items.forEach(v=>el.add(new Option(v,v,false,v===current)));};const json=async r=>{if(!r.ok)throw new Error('Lookup failed');return r.json();};async function loadStates(){if(!country.value){fill(state,[],'Select country first');fill(city,[],'Select state first');return;}const name=country.options[country.selectedIndex].dataset.name;fill(state,[],'Loading states...');fill(city,[],'Select state first');try{fill(state,await json(await fetch(`{{route('profile.lookups.states')}}?country=${encodeURIComponent(name)}`,{headers:{Accept:'application/json'}})),'Select state',state.dataset.current);if(state.value)loadCities();}catch(e){fill(state,[],'Unable to load states');}}async function loadCities(){if(!state.value){fill(city,[],'Select state first');return;}const name=country.options[country.selectedIndex].dataset.name;fill(city,[],'Loading cities...');try{fill(city,await json(await fetch(`{{route('profile.lookups.cities')}}?country=${encodeURIComponent(name)}&state=${encodeURIComponent(state.value)}`,{headers:{Accept:'application/json'}})),'Select city',city.dataset.current);}catch(e){fill(city,[],'Unable to load cities');}}country.addEventListener('change',()=>{state.dataset.current='';city.dataset.current='';loadStates();});state.addEventListener('change',()=>{city.dataset.current='';loadCities();});if(country.value)loadStates();});</script>
